<?php
require_once '../includes/auth.php'; requireActiveUser(); requireTenantContext(); requireModulePermission('hotspot','view');
global $conn;$tenantId=(int)getCurrentTenantId();$rows=[];$q=$conn->prepare("SELECT * FROM hotspot_vouchers WHERE tenant_id=? ORDER BY id DESC LIMIT 500");if($q){$q->bind_param('i',$tenantId);$q->execute();$z=$q->get_result();while($r=$z->fetch_assoc())$rows[]=$r;$q->close();}
$pageTitle='Hotspot Vouchers';require_once '../includes/header.php';?><div class="dashboard-card"><div class="page-header"><div><h2>Hotspot Vouchers</h2><p>Manage voucher inventory, batches, activation and expiry.</p></div></div><div class="table-responsive"><table><thead><tr><th>Code</th><th>Batch</th><th>Price</th><th>Status</th><th>Activated</th><th>Expires</th></tr></thead><tbody><?php foreach($rows as $x):?><tr><td><?=e($x['code'])?></td><td><?=e($x['batch_reference']??'—')?></td><td><?=e(formatMoney($x['price']))?></td><td><?=e($x['status'])?></td><td><?=e($x['activated_at']??'—')?></td><td><?=e($x['expires_at']??'—')?></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="6">No vouchers created yet.</td></tr><?php endif;?></tbody></table></div></div><?php require_once '../includes/footer.php';?>